import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

fused_op_source = """
#include <torch/extension.h>
#include <cuda_runtime.h>

__global__ void fused_sub_mul_relu_kernel(const float* input, float* output, int size, float sub_val, float mul_val) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (idx < size) {
        float val = input[idx];
        val = (val - sub_val) * mul_val;
        output[idx] = fmaxf(val, 0.0f);
    }
}

torch::Tensor fused_sub_mul_relu_cuda(torch::Tensor input, float sub_val, float mul_val) {
    auto output = torch::empty_like(input);
    int size = input.numel();
    const int block_size = 256;
    int num_blocks = (size + block_size - 1) / block_size;
    fused_sub_mul_relu_kernel<<<num_blocks, block_size>>>(input.data_ptr<float>(), output.data_ptr<float>(), size, sub_val, mul_val);
    return output;
}
"""

fused_op_cpp = "torch::Tensor fused_sub_mul_relu_cuda(torch::Tensor input, float sub_val, float mul_val);"

fused_op = load_inline(
    name='fused_op',
    cpp_sources=fused_op_cpp,
    cuda_sources=fused_op_source,
    functions=['fused_sub_mul_relu_cuda'],
    verbose=True
)

class ModelNew(nn.Module):
    def __init__(self, in_features, out_features, subtract_value, multiply_value):
        super(ModelNew, self).__init__()
        self.linear = nn.Linear(in_features, out_features)
        self.subtract_value = subtract_value
        self.multiply_value = multiply_value

    def forward(self, x):
        x = self.linear(x)
        x = fused_op.fused_sub_mul_relu_cuda(x, self.subtract_value, self.multiply_value)
        return x
